+/**
+ * Copyright IBM Corp. 2016, 2018
+ *
+ * This source code is licensed under the Apache-2.0 license found in the
+ * LICENSE file in the root directory of this source tree.
+ */
+
+import React from 'react';
+import OverflowMenu from '../OverflowMenu';
+import OverflowMenuItem from '../OverflowMenuItem';
+import { render } from '@testing-library/react';
+
+describe('OverflowMenu Deprecation Warnings', () => {
+  const originalConsoleWarn = console.warn;
+  let mockWarn;
+
+  beforeEach(() => {
+    mockWarn = jest.fn();
+    console.warn = mockWarn;
+  });
+
+  afterEach(() => {
+    console.warn = originalConsoleWarn;
+  });
+
+  it('should not show deprecation warning when light prop is not used', () => {
+    render(
+      <OverflowMenu ariaLabel="Test Menu">
+        <OverflowMenuItem itemText="Option 1" />
+      </OverflowMenu>
+    );
+
+    // Check if the warning about light prop was not called
+    const lightWarningCalled = mockWarn.mock.calls.some(
+      (call) => 
+        call[0] && 
+        typeof call[0] === 'string' && 
+        call[0].includes('light')
+    );
+    
+    expect(lightWarningCalled).toBe(false);
+  });
+});
